package com.shortener;

public class URLShortenerException extends RuntimeException {
    public URLShortenerException(String message) {
        super(message);
    }

    public URLShortenerException(String message, Throwable cause) {
        super(message, cause);
    }
}

package com.shortener;

public class InvalidURLException extends URLShortenerException {
    public InvalidURLException(String url) {
        super("Invalid URL: " + url);
    }
}

package com.shortener;

public class URLNotFoundException extends URLShortenerException {
    public URLNotFoundException(String shortCode) {
        super("No URL found for code: " + shortCode);
    }
}

package com.shortener;

import java.net.URI;
import java.net.URISyntaxException;
import java.util.Map;
import java.util.Optional;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.logging.Level;
import java.util.logging.Logger;

public class URLShortener {
    private static final Logger LOGGER = Logger.getLogger(URLShortener.class.getName());
    private static final String BASE_URL = "https://short.url/";
    private static final int CODE_LENGTH = 6;
    private static final String ALPHABET = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    private final Map<String, String> urlMap = new ConcurrentHashMap<>();
    private final Map<String, String> reverseMap = new ConcurrentHashMap<>();
    private final AtomicLong counter = new AtomicLong();

    public String shorten(String longUrl) {
        LOGGER.info(() -> "Shortening URL: " + longUrl);

        validateUrl(longUrl);

        String existingCode = reverseMap.get(longUrl);
        if (existingCode != null) {
            LOGGER.fine(() -> "URL already shortened: " + existingCode);
            return BASE_URL + existingCode;
        }

        String shortCode = generateCode();
        urlMap.put(shortCode, longUrl);
        reverseMap.put(longUrl, shortCode);

        LOGGER.info(() -> "Shortened " + longUrl + " -> " + shortCode);
        return BASE_URL + shortCode;
    }

    public String expand(String shortUrl) {
        LOGGER.info(() -> "Expanding URL: " + shortUrl);

        String code = extractCode(shortUrl);
        String longUrl = Optional.ofNullable(urlMap.get(code))
                .orElseThrow(() -> {
                    LOGGER.warning(() -> "Code not found: " + code);
                    return new URLNotFoundException(code);
                });

        LOGGER.fine(() -> "Expanded " + code + " -> " + longUrl);
        return longUrl;
    }

    public boolean exists(String shortUrl) {
        String code = extractCode(shortUrl);
        return urlMap.containsKey(code);
    }

    public int size() {
        return urlMap.size();
    }

    private void validateUrl(String url) {
        if (url == null || url.isBlank()) {
            throw new InvalidURLException(url);
        }
        try {
            URI uri = new URI(url);
            if (uri.getScheme() == null || uri.getHost() == null) {
                throw new InvalidURLException(url);
            }
        } catch (URISyntaxException e) {
            LOGGER.log(Level.WARNING, "URL validation failed: " + url, e);
            throw new InvalidURLException(url);
        }
    }

    private String extractCode(String shortUrl) {
        if (shortUrl == null || !shortUrl.startsWith(BASE_URL)) {
            throw new URLShortenerException("Invalid short URL format: " + shortUrl);
        }
        return shortUrl.substring(BASE_URL.length());
    }

    private String generateCode() {
        long id = counter.incrementAndGet();
        StringBuilder code = new StringBuilder(CODE_LENGTH);
        long remaining = id;
        for (int i = 0; i < CODE_LENGTH; i++) {
            code.append(ALPHABET.charAt((int) (remaining % ALPHABET.length())));
            remaining /= ALPHABET.length();
        }
        return code.toString();
    }
}

package com.shortener;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.NullAndEmptySource;
import org.junit.jupiter.params.provider.ValueSource;

import static org.junit.jupiter.api.Assertions.*;

class URLShortenerTest {
    private URLShortener shortener;

    @BeforeEach
    void setUp() {
        shortener = new URLShortener();
    }

    @Test
    void shorten_validUrl_returnsShortUrl() {
        String result = shortener.shorten("https://example.com");
        assertTrue(result.startsWith("https://short.url/"));
        assertEquals(28, result.length());
    }

    @Test
    void shorten_sameUrl_returnsSameCode() {
        String first = shortener.shorten("https://example.com");
        String second = shortener.shorten("https://example.com");
        assertEquals(first, second);
    }

    @Test
    void shorten_differentUrls_returnsDifferentCodes() {
        String first = shortener.shorten("https://example.com");
        String second = shortener.shorten("https://other.com");
        assertNotEquals(first, second);
    }

    @ParameterizedTest
    @NullAndEmptySource
    @ValueSource(strings = {"   ", "not-a-url", "http://"})
    void shorten_invalidUrl_throwsException(String url) {
        assertThrows(InvalidURLException.class, () -> shortener.shorten(url));
    }

    @Test
    void expand_validCode_returnsOriginalUrl() {
        String shortUrl = shortener.shorten("https://example.com/path?q=1");
        assertEquals("https://example.com/path?q=1", shortener.expand(shortUrl));
    }

    @Test
    void expand_unknownCode_throwsException() {
        assertThrows(URLNotFoundException.class, () -> shortener.expand("https://short.url/unknown"));
    }

    @Test
    void expand_invalidFormat_throwsException() {
        assertThrows(URLShortenerException.class, () -> shortener.expand("invalid"));
    }

    @Test
    void expand_nullUrl_throwsException() {
        assertThrows(URLShortenerException.class, () -> shortener.expand(null));
    }

    @Test
    void exists_existingUrl_returnsTrue() {
        String shortUrl = shortener.shorten("https://example.com");
        assertTrue(shortener.exists(shortUrl));
    }

    @Test
    void exists_unknownUrl_returnsFalse() {
        assertFalse(shortener.exists("https://short.url/unknown"));
    }

    @Test
    void size_empty_returnsZero() {
        assertEquals(0, shortener.size());
    }

    @Test
    void size_afterShortening_returnsCount() {
        shortener.shorten("https://one.com");
        shortener.shorten("https://two.com");
        assertEquals(2, shortener.size());
    }

    @Test
    void size_duplicateUrl_doesNotIncrement() {
        shortener.shorten("https://example.com");
        shortener.shorten("https://example.com");
        assertEquals(1, shortener.size());
    }
}
